import { appendQueryPair } from './query_codec.mjs';
import { composeUrlReference, parseUrlReference } from './url_reference.mjs';

export class FurlQuery {
  #rawQuery;

  constructor(rawQuery = '') {
    this.#rawQuery = rawQuery;
  }

  add(entries) {
    for (const [key, value] of Object.entries(entries)) {
      this.#rawQuery = appendQueryPair(this.#rawQuery, key, value);
    }

    return this;
  }

  toString() {
    return this.#rawQuery;
  }
}

export class FurlLike {
  #parts;
  #query;

  constructor(input) {
    this.#parts = parseUrlReference(input);
    this.#query = new FurlQuery(this.#parts.query);
  }

  get host() {
    return this.#parts.host;
  }

  get path() {
    return this.#parts.path;
  }

  get query() {
    return this.#query;
  }

  get scheme() {
    return this.#parts.scheme;
  }

  get url() {
    return composeUrlReference({
      ...this.#parts,
      query: this.#query.toString(),
    });
  }
}

export function createFurlLike(input) {
  return new FurlLike(input);
}

