  if (index === -1) {
    return { before: text, after: null };
  }

  return {
    before: text.slice(0, index),
    after: text.slice(index + delimiter.length),
  };
}

function splitScheme(text) {
  const colonIndex = text.indexOf(':');
  const slashIndex = text.indexOf('/');

  if (colonIndex === -1 || (slashIndex !== -1 && colonIndex > slashIndex)) {
    return { scheme: null, rest: text };
  }

  return {
    scheme: text.slice(0, colonIndex),
    rest: text.slice(colonIndex + 1),
  };
}

export function extractHost(authority) {
  if (authority === null) {
    return null;
  }

  let hostPort = authority;
  const atIndex = hostPort.lastIndexOf('@');
  if (atIndex !== -1) {
    hostPort = hostPort.slice(atIndex + 1);
  }

  if (hostPort.startsWith('[')) {
    const closingBracketIndex = hostPort.indexOf(']');
    if (closingBracketIndex !== -1) {
      return hostPort.slice(0, closingBracketIndex + 1);
    }
  }

  const portSeparatorIndex = hostPort.lastIndexOf(':');
  if (portSeparatorIndex === -1) {
    return hostPort;
  }

  return hostPort.slice(0, portSeparatorIndex);
}

export function parseUrlReference(input) {
  const text = String(input);
  const { before: withoutFragment, after: fragment } = splitOnce(text, '#');
  const { before: withoutQuery, after: query } = splitOnce(withoutFragment, '?');
  const { scheme, rest } = splitScheme(withoutQuery);

  let authority = null;
  let path = rest;

  if (rest.startsWith('//')) {
    const authorityAndPath = rest.slice(2);
    const pathStartIndex = authorityAndPath.indexOf('/');
    if (pathStartIndex === -1) {
      authority = authorityAndPath;
      path = '';
    } else {
      authority = authorityAndPath.slice(0, pathStartIndex);
      path = authorityAndPath.slice(pathStartIndex);
    }
  }

  return {
    authority,
    fragment,
    host: extractHost(authority),
    path,
    query: query === null ? '' : query,
    scheme,
  };
}

export function composeUrlReference({ authority, fragment, path, query, scheme }) {
  let text = '';

  if (scheme !== null) {
    text += `${scheme}:`;
  }

  if (authority !== null) {
    text += `//${authority}`;
  }

  text += path;

  if (query !== '') {
    text += `?${query}`;
  }

  if (fragment !== null) {
    text += `#${fragment}`;
  }

  return text;
}

