import { CommandLineExit, parseCommandLineArgs } from './lib/argparse_compat.mjs';
import { createFurlLike } from './lib/furl_like.mjs';
import { writePythonPrintLine } from './lib/python_print.mjs';

export function main(argv = process.argv.slice(2)) {
  const args = parseCommandLineArgs(argv);
  const f = createFurlLike(args.a);

  writePythonPrintLine(f.scheme);
  writePythonPrintLine(f.host);
  writePythonPrintLine(f.path);
  writePythonPrintLine(f.query.add({ [args.b]: args.c }));
  writePythonPrintLine(f.url);
}

try {
  main();
} catch (error) {
  if (error instanceof CommandLineExit) {
    process.exit(error.code);
  }

  throw error;
}

