function encodeWithUppercasePercentEscapes(text) {
  return encodeURIComponent(text).replace(/[!'()*]/g, (character) =>
    `%${character.charCodeAt(0).toString(16).toUpperCase()}`,
  );
}

export function encodeQueryComponent(value) {
  return encodeWithUppercasePercentEscapes(String(value)).replace(/%20/g, '+');
}

export function encodeQueryPair(key, value) {
  return `${encodeQueryComponent(key)}=${encodeQueryComponent(value)}`;
}

export function appendQueryPair(rawQuery, key, value) {
  const nextPair = encodeQueryPair(key, value);
  return rawQuery === '' ? nextPair : `${rawQuery}&${nextPair}`;
}

