const PROGRAM_NAME = 'test6_executable';
const USAGE_LINE = `usage: ${PROGRAM_NAME} [-h] --a A --b B --c C\n`;
const HELP_TEXT = `${USAGE_LINE}\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n  --c C\n`;
const OPTION_TO_KEY = new Map([
  ['--a', 'a'],
  ['--b', 'b'],
  ['--c', 'c'],
]);

export class CommandLineExit extends Error {
  constructor(code) {
    super(`Command line exit: ${code}`);
    this.code = code;
  }
}

function writeUsageAndExit(stderr, message) {
  stderr.write(USAGE_LINE);
  stderr.write(`${PROGRAM_NAME}: error: ${message}\n`);
  throw new CommandLineExit(2);
}

function writeHelpAndExit(stdout) {
  stdout.write(HELP_TEXT);
  throw new CommandLineExit(0);
}

export function parseCommandLineArgs(
  argv,
  io = { stdout: process.stdout, stderr: process.stderr },
) {
  const values = {
    a: undefined,
    b: undefined,
    c: undefined,
  };
  const extras = [];
  let afterDoubleDash = false;

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (!afterDoubleDash) {
      if (token === '-h' || token === '--help' || (token.startsWith('-h') && !token.startsWith('-h='))) {
        writeHelpAndExit(io.stdout);
      }

      if (token.startsWith('--help=')) {
        writeUsageAndExit(io.stderr, `argument -h/--help: ignored explicit argument '${token.slice(7)}'`);
      }

      if (token.startsWith('-h=')) {
        writeUsageAndExit(io.stderr, `argument -h/--help: ignored explicit argument '${token.slice(3)}'`);
      }

      if (token === '--') {
        afterDoubleDash = true;
        continue;
      }

      if (token.startsWith('--')) {
        const equalsIndex = token.indexOf('=');
        const option = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
        const key = OPTION_TO_KEY.get(option);

        if (key === undefined) {
          extras.push(token);
          continue;
        }

        if (equalsIndex !== -1) {
          values[key] = token.slice(equalsIndex + 1);
          continue;
        }

        const next = argv[index + 1];
        if (next === undefined || next === '--' || next.startsWith('-')) {
          writeUsageAndExit(io.stderr, `argument ${option}: expected one argument`);
        }

        values[key] = next;
        index += 1;
        continue;
      }
    }

    extras.push(token);
  }

  const missing = [];
  for (const option of ['--a', '--b', '--c']) {
    if (values[OPTION_TO_KEY.get(option)] === undefined) {
      missing.push(option);
    }
  }

  if (missing.length > 0) {
    writeUsageAndExit(io.stderr, `the following arguments are required: ${missing.join(', ')}`);
  }

  if (extras.length > 0) {
    writeUsageAndExit(io.stderr, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return values;
}

